{"path":"about.html","content":"<!doctype html>
<html lang='en'>
<head>
  <meta charset='utf-8'>
  <meta name='viewport' content='width=device-width,initial-scale=1'>
  <title>About — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#0f1720;--card:#0b1220;--muted:#9aa6b2;--accent:#84d4c8;--glass:rgba(255,255,255,0.03);--radius:14px}
    *{box-sizing:border-box}
    html,body{height:100%}
    body{margin:0;font-family:system-ui,-apple-system,Segoe UI,Roboto,'Helvetica Neue',Arial;color:#e6eef0;background:linear-gradient(180deg,var(--bg),#071018);-webkit-font-smoothing:antialiased}
    header{position:sticky;top:0;background:linear-gradient(180deg,rgba(6,12,16,0.6),transparent);backdrop-filter:blur(6px);z-index:30;padding:18px 28px;display:flex;align-items:center;gap:18px}
    .brand{display:flex;align-items:center;gap:12px}
    .logo{width:46px;height:46px;border-radius:10px;background:linear-gradient(135deg,var(--accent),#2ec6b6);display:grid;place-items:center;color:#042428;font-weight:700}
    nav a{color:var(--muted);text-decoration:none;margin-right:14px;font-size:14px}
    nav a.cta{background:var(--accent);color:#042428;padding:8px 12px;border-radius:10px;font-weight:600}
    main{padding:36px 28px;max-width:980px;margin:0 auto}
    .hero{display:grid;grid-template-columns:1fr;gap:18px;padding:38px;background:linear-gradient(180deg,rgba(255,255,255,0.02),transparent);border-radius:16px;margin-bottom:22px;position:relative;overflow:hidden}
    .hero .pattern{position:absolute;right:-40px;top:-40px;opacity:0.14;width:360px;height:360px;filter:blur(6px);}
    .hero h1{margin:0;color:#e9fbfb;font-size:28px}
    .lead{color:var(--muted);margin-top:8px;line-height:1.5}
    .columns{display:grid;grid-template-columns:1fr 320px;gap:20px}
    .card{background:var(--card);padding:18px;border-radius:12px}
    .pillars{display:grid;gap:12px}
    .pillar{background:var(--glass);padding:12px;border-radius:10px}
    .meta{display:flex;gap:10px;align-items:center;margin-top:12px}
    .meta span{color:var(--muted);font-size:13px}
    .btn-row{display:flex;gap:12px;margin-top:14px}
    button,button[role='button']{background:transparent;border:1px solid rgba(255,255,255,0.06);color:#e9fbfb;padding:10px 12px;border-radius:10px;cursor:pointer}
    button.primary{background:var(--accent);color:#042428;border:none}
    .case{margin-top:18px;color:var(--muted);font-size:14px}
    footer{margin:32px 0;text-align:center;color:var(--muted);font-size:13px}

    /* reveal animation */
    .reveal{opacity:0;transform:translateY(18px);transition:opacity 520ms cubic-bezier(.2,.9,.2,1),transform 520ms cubic-bezier(.2,.9,.2,1)}
    .reveal.in{opacity:1;transform:none}

    /* modal */
    .modal-backdrop{position:fixed;inset:0;background:linear-gradient(0deg,rgba(2,6,11,0.6),rgba(2,6,11,0.85));display:none;align-items:center;justify-content:center;padding:28px;z-index:60}
    .modal{width:100%;max-width:680px;background:#051015;border-radius:14px;padding:20px;color:#eaf6f5}
    .modal .steps{display:grid;gap:12px}
    .meter{height:8px;background:rgba(255,255,255,0.06);border-radius:8px;overflow:hidden}
    .meter > i{display:block;height:100%;width:0;background:linear-gradient(90deg,#a7fff4,#4fd9c9);transition-width:400ms linear}
    .close{float:right;background:transparent;border:none;color:var(--muted);cursor:pointer}
    .vis{height:120px;display:grid;place-items:center}
    .ring{width:88px;height:88px;border-radius:50%;background:conic-gradient(#7ff0df 0 0,#042428 0);display:grid;place-items:center;color:#042428;font-weight:700}

    @media(min-width:880px){.hero{grid-template-columns:1fr 320px}.columns{grid-template-columns:1fr 320px}}
  </style>
</head>
<body>
  <header>
    <div class='brand'>
      <div class='logo' aria-hidden='true'>SB</div>
      <div>
        <div style='font-weight:700;color:#eaf6f5'>{{BUSINESS_NAME}}</div>
        <div style='font-size:12px;color:var(--muted)'>{{TAGLINE}}</div>
      </div>
    </div>
    <nav aria-label='Primary navigation' style='margin-left:auto'>
      <a href='index.html'>Home</a>
      <a href='events.html'>Gatherings</a>
      <a href='private-sessions.html'>Private Sessions</a>
      <a href='pricing.html'>Invest</a>
      <a href='about.html' class='cta'>About the Practice</a>
      <a href='faq.html'>Answers</a>
      <a href='book.html'>Reserve</a>
      <a href='contact.html'>Connect</a>
    </nav>
  </header>

  <main>
    <section class='hero card reveal' aria-labelledby='about-hero'>
      <svg class='pattern' viewBox='0 0 200 200' xmlns='http://www.w3.org/2000/svg' aria-hidden='true'>
        <defs>
          <pattern id='p1' x='0' y='0' width='20' height='20' patternUnits='userSpaceOnUse'>
            <circle cx='2' cy='2' r='1.6' fill='#4fd9c9'/>
            <circle cx='12' cy='12' r='1.6' fill='#7ff0df'/>
          </pattern>
        </defs>
        <rect width='100%' height='100%' fill='url(#p1)' opacity='0.9'/>
      </svg>
      <div>
        <h1 id='about-hero'>An intentional room for deep listening</h1>
        <p class='lead'>We guide focused sessions that use layered tones, gentle percussion, and guided centering to help you set an intention, settle the nervous system, and leave with practical tools for daily restoration.</p>
        <div class='btn-row'>
          <button class='primary' onclick='location.href="{{PRIMARY_CTA_URL}}"'>{{PRIMARY_CTA_LABEL}}</button>
          <button id='tryNow'>Try it now</button>
        </div>
      </div>
      <aside class='card' aria-hidden='false'>
        <div style='font-weight:700;color:#eaf6f5'>Offerings</div>
        <div class='meta'>
          <span style='font-weight:700;color:#cffbf3'>Echo Session</span>
          <span>— 45 minutes, group</span>
        </div>
        <div class='meta'>
          <span style='font-weight:700;color:#cffbf3'>Root Session</span>
          <span>— 75 minutes, deep practice</span>
        </div>
        <div style='margin-top:12px;color:var(--muted);font-size:13px'>Sessions are framed as focused, practical gatherings that provide tools you can use off the mat.</div>
      </aside>
    </section>

    <section class='reveal' aria-labelledby='myth'>
      <h2 id='myth' style='color:#eaf6f5'>What people misunderstand</h2>
      <div class='pillars' style='margin-top:10px'>
        <div class='pillar'>Myth: Sound baths are passive spectacles.
          <div style='color:var(--muted);margin-top:8px'>Reality: We design structure: intention, measured pacing, and takeaways for day to day renewal.</div>
        </div>
        <div class='pillar'>Myth: You need prior practice.
          <div style='color:var(--muted);margin-top:8px'>Reality: These sessions meet any starting point and prioritize safety and clarity.</div>
        </div>
        <div class='pillar'>Myth: They are only for rest.
          <div style='color:var(--muted);margin-top:8px'>Reality: Many leave with clearer decision focus and improved breath regulation.</div>
        </div>
      </div>
    </section>

    <section class='reveal' aria-labelledby='pillars' style='margin-top:18px'>
      <h2 id='pillars' style='color:#eaf6f5'>Practice pillars</h2>
      <div class='columns' style='margin-top:12px'>
        <div>
          <div class='card'>
            <h3 style='margin-top:0;color:#c9fff6'>Intention first</h3>
            <div class='case'>Every session begins with a short guided settling and an explicit intention. This frames the listening and helps integrate findings after the sound work.</div>
          </div>

          <div class='card' style='margin-top:12px'>
            <h3 style='color:#c9fff6'>Measured layering</h3>
            <div class='case'>We use a modest palette of sustaining tones, light percussive textures, and silence so participants can track changes and learn to self-regulate.</div>
          </div>

          <div class='card' style='margin-top:12px'>
            <h3 style='color:#c9fff6'>Tools to take home</h3>
            <div class='case'>Simple breath cues and short journaling prompts offered at the end for ongoing practice at home.</div>
          </div>
        </div>

        <aside class='card'>
          <h4 style='margin:0;color:#e9fbfb'>Quick notes</h4>
          <div class='meta' style='margin-top:10px'>
            <span>Location:</span><span style='color:var(--muted)'> {{CITY}}, {{STATE}}</span>
          </div>
          <div class='meta'>
            <span>Contact:</span><span style='color:var(--muted)'> {{PHONE}} • {{EMAIL}}</span>
          </div>
          <div style='margin-top:10px;color:var(--muted)'>Small group sizes and a calm, dim studio setting. We ask that you arrive 10 minutes early to settle.</div>
        </aside>
      </div>
    </section>

    <section class='reveal' aria-labelledby='case' style='margin-top:18px'>
      <h2 id='case' style='color:#eaf6f5'>Case notes</h2>
      <div class='card' style='margin-top:10px'>
        <p class='case'>Clients report clearer decision moments, steadier respiration during stress, and a less reactive nervous system after a short series. The work is framed for practical change, not only scenic rest.</p>
      </div>
    </section>

    <section class='reveal' style='margin-top:22px'>
      <div class='card'>
        <h3 style='margin-top:0;color:#e9fbfb'>Ready to reserve a place</h3>
        <p style='color:var(--muted)'>When you are ready, choose a session length that fits your schedule. If you are unfamiliar with sound or have health concerns please review our questions on the booking page.</p>
        <div style='margin-top:12px'>
          <button class='primary' onclick='location.href="book.html"'>Reserve a session</button>
          <button onclick='location.href="contact.html"' style='margin-left:8px'>Ask a question</button>
        </div>
      </div>
    </section>

    <footer>
      <div>Questions? Call {{PHONE}} or email {{EMAIL}}</div>
      <div style='margin-top:6px'>&copy; <span id='year'></span> {{BUSINESS_NAME}}</div>
    </footer>
  </main>

  <div id='modalBackdrop' class='modal-backdrop' role='dialog' aria-modal='true' aria-hidden='true'>
    <div class='modal' role='document'>
      <button class='close' id='closeModal' aria-label='Close'>✕</button>
      <h3 style='margin-top:0'>A short guided focus</h3>
      <p style='color:var(--muted)'>This three part exercise mixes breath, a single-minute journal prompt, and a brief intention setting. No audio required. Click start when you are ready.</p>
      <div class='steps' id='exerciseSteps'>
        <div class='vis'>
          <div class='ring' id='ring'>3</div>
        </div>
        <div class='meter' aria-hidden='true'><i id='progressBar' style='width:0%'></i></div>
        <div style='color:var(--muted);font-size:14px' id='stepText'>Ready</div>
      </div>
      <div style='margin-top:12px;display:flex;gap:8px'>
        <button id='startExercise' class='primary'>Start</button>
        <button id='cancelExercise'>Cancel</button>
      </div>
    </div>
  </div>

  <script>
    // set year
    document.getElementById('year').textContent = new Date().getFullYear();

    // scroll reveal with prefers-reduced-motion support
    (function(){
      const prefers = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
      const els = document.querySelectorAll('.reveal');
      if(prefers){
        els.forEach(e=>e.classList.add('in'));
        return;
      }
      const io = new IntersectionObserver((entries)=>{
        entries.forEach(ent=>{
          if(ent.isIntersecting){
            ent.target.classList.add('in');
            io.unobserve(ent.target);
          }
        });
      },{threshold:0.12});
      els.forEach(e=>io.observe(e));
    })();

    // guided exercise modal
    (function(){
      const tryBtn = document.getElementById('tryNow');
      const backdrop = document.getElementById('modalBackdrop');
      const close = document.getElementById('closeModal');
      const start = document.getElementById('startExercise');
      const cancel = document.getElementById('cancelExercise');
      const ring = document.getElementById('ring');
      const text = document.getElementById('stepText');
      const bar = document.getElementById('progressBar');

      let timer = null;
      const steps = [
        {label:'Find a comfortable seat. Close your eyes if safe. 3 breaths in 60 seconds.', dur:60, type:'breath'},
        {label:'One minute journal: note one small thing you want to carry from today.', dur:60, type:'journal'},
        {label:'Set a short intention for the next hour. Hold it quietly for 30 seconds.', dur:30, type:'intention'}
      ];

      function open(){backdrop.style.display='flex';backdrop.setAttribute('aria-hidden','false');}
      function closeModal(){backdrop.style.display='none';backdrop.setAttribute('aria-hidden','true');clearInterval(timer);bar.style.width='0%';ring.textContent='3';text.textContent='Ready';}

      tryBtn.addEventListener('click',open);
      close.addEventListener('click',closeModal);
      cancel.addEventListener('click',closeModal);
      backdrop.addEventListener('click',e=>{if(e.target===backdrop)closeModal();});

      start.addEventListener('click',()=>{
        let i=0;open();runStep(i);
        function runStep(idx){
          const s = steps[idx];
          let elapsed=0;bar.style.width='0%';
          text.textContent = s.label;
          ring.textContent = Math.ceil(s.dur/10).toString();
          timer = setInterval(()=>{
            elapsed++;
            bar.style.width = Math.round(100*(elapsed/s.dur))+'%';
            // ring number updates per 10% of step
            const left = Math.max(0, Math.ceil((s.dur-elapsed)/10));
            ring.textContent = left || '0';
            if(elapsed>=s.dur){
              clearInterval(timer);
              if(idx+1<steps.length){
                setTimeout(()=>runStep(idx+1),450);
              } else {
                text.textContent='Complete. Carry your intention.';
                setTimeout(closeModal,1200);
              }
            }
          },1000);
        }
      });
    })();
  </script>
</body>
</html>"} 
