  <style>
    :root{--bg:#07121a;--card:#081620;--muted:#95a7ad;--accent:#66d9c7}
    body{margin:0;font-family:Inter,system-ui,Segoe UI,Roboto,Arial;color:#e8fbf9;background:linear-gradient(180deg,var(--bg),#021018);-webkit-font-smoothing:antialiased}
